let petState=null,petLoaded=false,petLoading=false,petBusy=false,petMessage='',petWaitUntil=0,petShopCategory='character';
const petStageNames=['새싹집','아기 보금이','인턴 보금이','든든한 보금이'];
const petActionNames={feed:['🍚','밥 먹기','든든하게 한 끼'],rest:['🌙','쉬기','포근한 낮잠'],clean:['🧹','방 청소','보금자리 반짝'],study:['📖','함께 공부','인턴의 한 걸음']};
async function petRequest(path='',data){const r=await fetch('/api/pet'+path,{credentials:'same-origin',...(data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{})});const result=await r.json();if(!r.ok)throw Error(result.error||'보금이를 불러오지 못했어요.');return result;}
async function loadPet(){if(petLoading)return;petLoading=true;try{const d=await petRequest();petState=d.pet;petLoaded=true;petWaitUntil=Date.now()+Number(d.pet?.care_wait||0)*1000;if(location.hash==='#pet')renderPetPage();}catch(error){if(location.hash==='#pet'){const app=document.querySelector('#pet-app');if(app)app.innerHTML='<p class="pet-notice" role="alert">'+esc(error.message)+'</p><button class="primary" id="pet-retry">다시 불러오기</button>';}}finally{petLoading=false;}}
function petSprite(stage,extra=''){return `<div class="bogeumi-sprite stage-${stage} ${extra}" role="img" aria-label="${petStageNames[stage]} 캐릭터"></div>`;}
function petAvatar(stage,look='',color=''){
 const anchors=[{x:54,y:65,span:14,roof:42,neck:79},{x:41,y:57,span:18,roof:30,neck:73},{x:53,y:45,span:16,roof:24,neck:60},{x:43,y:38,span:18,roof:18,neck:54}];
 const a=anchors[stage],x=a.x,y=a.y,d=a.span/2;let art='';
 if(look==='look-scholar')art=`<g fill="#f2f8ff" fill-opacity=".16" stroke="#365474" stroke-width="1.5"><circle cx="${x-d}" cy="${y}" r="5.1"/><circle cx="${x+d}" cy="${y}" r="5.1"/><path d="M${x-d+5} ${y} Q${x} ${y-3} ${x+d-5} ${y}" fill="none"/><path d="M${x-d-5} ${y-1}l-3-1 M${x+d+5} ${y-1}l3-1"/></g>`;
 if(look==='look-ribbon')art=`<g transform="translate(${x+15} ${a.roof}) rotate(18)"><path d="M0 0Q-13-11-12-2Q-13 7 0 2Q13 8 12-2Q13-11 0 0" fill="#e58aa8" stroke="#c76888" stroke-width=".8"/><path d="M-2 2l-5 10 5-2 2-6 3 7 4 1-5-11" fill="#e58aa8"/><ellipse rx="2.5" ry="3" fill="#f4aec5"/></g>`;
 if(look==='look-music')art=`<path d="M${x-d-9} ${y+1}V${y-9}Q${x} ${y-38} ${x+d+9} ${y-9}V${y+1}" fill="none" stroke="#667699" stroke-width="3"/><g fill="#8e9fc2" stroke="#536485" stroke-width="1"><rect x="${x-d-12}" y="${y-5}" width="6" height="14" rx="3"/><rect x="${x+d+6}" y="${y-5}" width="6" height="14" rx="3"/></g>`;
 if(look==='look-cozy')art=`<g transform="translate(${x} ${a.neck})"><path d="M-17-3Q0 4 17-3L16 2Q0 9-16 2Z" fill="#da9175" stroke="#b8745b" stroke-width=".8"/><path d="M8 2l-2 15 6 1 2-15" fill="#e6a184" stroke="#b8745b" stroke-width=".6"/><path d="M7 14l6 1" stroke="#f5cbb2" stroke-width="1.3"/></g>`;
 return `<div class="pet-avatar ${color}" role="img" aria-label="${petStageNames[stage]}${look?' · '+({'look-scholar':'안경','look-ribbon':'리본','look-music':'헤드폰','look-cozy':'목도리'}[look]):''}">${petSprite(stage)}<svg class="pet-fitted-accessory" viewBox="0 0 100 100" aria-hidden="true">${art}</svg></div>`;
}
function petRoom(p){const roomClasses=p.equipped.filter(k=>k.startsWith('wall-')||k.startsWith('rug-')||k.startsWith('floor-')).join(' ');const look=p.equipped.find(k=>k.startsWith('look-'))||'';const color=p.equipped.find(k=>k.startsWith('color-'))||'';return `<div class="pet-room ${roomClasses} ${p.energy<45?'pet-room-sleepy':''}" aria-label="${esc(p.name)}의 방"><div class="pet-room-wall"><div class="pet-window"><span class="pet-sun"></span><span class="pet-cloud"></span></div><div class="pet-wall-frame">HOME<br><small>작은 오늘, 든든한 내일</small></div></div><div class="pet-floor"></div><div class="pet-rug"></div><div class="pet-cushion"></div>${p.equipped.includes('books')?'<div class="pet-bookshelf" aria-label="인턴 책장"><span>📘 📙 📗</span><span>📕 📘 📓</span></div>':''}${p.equipped.includes('plant')?'<div class="pet-plant" aria-label="작은 화분">🪴</div>':''}${p.equipped.includes('lamp')?'<div class="pet-lamp" aria-label="포근한 조명"><span></span></div>':''}${p.equipped.includes('sofa')?'<div class="pet-sofa" aria-label="구름 소파"><span></span></div>':''}${p.equipped.includes('clock')?'<div class="pet-clock" aria-label="곰돌이 시계">◷</div>':''}${p.equipped.includes('flowers')?'<div class="pet-flowers" aria-label="봄날 꽃병">🌷</div>':''}${p.equipped.includes('cat')?'<div class="pet-cat" aria-label="고양이 인형">🐱</div>':''}${p.equipped.includes('stars')?'<div class="pet-stars" aria-label="별빛 가랜드">✧ · ★ · ✧ · ★ · ✧</div>':''}<div class="pet-room-label">${esc(p.name)}의 보금자리</div><div class="pet-character">${petAvatar(p.stage,look,color)}<div class="pet-shadow"></div></div></div>`;}
function petMood(p){if(p.hunger<45)return '배가 조금 고파요. 같이 밥 먹을까요?';if(p.energy<45)return '잠깐 쉬면서 충전하고 싶어요.';if(p.hygiene<45)return '방을 함께 정리해 볼까요?';return ['오늘부터 우리 함께 지내요!','여기가 내 보금자리예요.','사원증을 달았어요! 같이 공부해요.','든든한 친구가 되어 줄게요.'][p.stage];}
function renderPetPage(){
 if(location.hash!=='#pet')return;
 if(!petLoaded){if(!document.querySelector('#pet-app'))content.innerHTML='<h1 class="view-title">보금이 키우기</h1><section class="panel" id="pet-app">작은 보금자리를 준비하고 있어요…</section>';loadPet();return;}
 if(!petState){content.innerHTML=`<h1 class="view-title">보금이 키우기</h1><section class="panel pet-welcome" id="pet-app"><span class="pet-eyebrow">MY LITTLE HOME</span><h2>작은 집에서 시작하는<br>우리의 인턴 생활</h2><div class="pet-welcome-art">${petSprite(0)}</div><p>밥을 챙기고, 쉬고, 함께 공부하며<br>나만의 보금이를 4단계로 키워 보세요.</p><form id="pet-adopt-form"><label>우리 친구 이름<input name="name" class="field" maxlength="12" value="보금이" required></label><button class="primary">보금이 맞이하기</button><p class="pet-notice" role="status"></p></form><small>내 계정에 저장되는 인턴 홈페이지 오리지널 캐릭터</small></section>`;return;}
 const p=petState,next=p.next_growth,previous=p.stages[p.stage].growth,progress=next?Math.min(100,(p.growth-previous)/(next-previous)*100):100;
 content.innerHTML=`<div class="pet-page" id="pet-app"><div class="pet-page-heading"><div><span class="pet-eyebrow">MY LITTLE HOME</span><h1 class="view-title">보금이 키우기</h1><p>함께 자라는 우리만의 작은 보금자리</p></div><span class="pet-coins">✦ 보금 코인 <strong>${p.coins}</strong></span></div><div class="pet-layout"><section class="pet-main"><div class="pet-name-row"><div><h2>${esc(p.name)} <span>${p.stage+1}단계 · ${esc(p.stage_name)}</span></h2><p>${esc(window.hfAuth.user.name)} 인턴의 친구</p></div><button type="button" class="pet-name-edit">이름 변경</button></div>${petRoom(p)}<p class="pet-speech">${esc(petMessage||petMood(p))}</p><div class="pet-actions">${Object.entries(petActionNames).map(([key,[icon,title,desc]])=>`<button type="button" data-pet-care="${key}" ${petBusy?'disabled':''}><span aria-hidden="true">${icon}</span><strong>${title}</strong><small>${p.rewarded.includes(key)?'오늘 보상 받음':'성장 +8 · 코인 +1'}</small></button>`).join('')}</div><p class="pet-notice" id="pet-action-status" role="status">${petBusy?'보금이를 돌보고 있어요…':''}</p></section><aside class="pet-side"><section class="panel pet-status-panel"><h2>오늘의 컨디션</h2>${[['hunger','포만감'],['happy','행복'],['energy','기운'],['hygiene','청결']].map(([key,label])=>`<div class="pet-stat"><div><span>${label}</span><strong>${Math.round(p[key])}</strong></div><progress max="100" value="${Math.round(p[key])}" aria-label="${label}"></progress></div>`).join('')}<p>조금씩 돌봐 주세요.<br>바쁜 날에도 보금이는 기다려 줘요.</p></section><section class="panel pet-growth"><h2>우리의 성장</h2><div class="pet-growth-caption"><span>${next?'다음 단계까지 '+(next-p.growth)+' 성장':'최종 단계에 도착했어요!'}</span><strong>${p.growth} 성장</strong></div><progress max="100" value="${progress}" aria-label="성장 진행률"></progress><ol>${p.stages.map((stage,i)=>`<li class="${i<=p.stage?'unlocked':'locked'}">${petSprite(i)}<span><small>${i+1}단계 · ${stage.growth} 성장</small>${esc(stage.name)}</span>${i===p.stage?'<em>지금</em>':''}</li>`).join('')}</ol></section></aside></div><section class="panel pet-coin-guide"><h2>보금 코인 모으기</h2><div><span>오늘의 출석 <strong>10 코인 / 하루</strong></span><span>순발력 대결 완료 <strong>10 코인 / 하루</strong></span><span>업무 · 청소 · 함께 식사 <strong>XP 2당 1 코인 · 하루 최대 20</strong></span><span>보금이 돌보기 <strong>하루 최대 4 코인</strong></span></div><p>활동 보상은 자동으로 모여요. 같은 활동은 한 번만 지급되고, 사용해도 홈페이지 XP는 그대로 유지됩니다.</p></section><section class="panel pet-decor"><div class="pet-store-heading"><div><h2>보금 상점</h2><p>마음에 드는 모습과 소품을 모아 나만의 방을 만들어 보세요.</p></div><small>구매한 아이템은 언제든 무료로 바꿀 수 있어요.</small></div><div class="pet-shop-tabs" role="tablist" aria-label="상점 분류">${[['character','캐릭터'],['color','색상'],['furniture','가구 · 소품'],['room','방 분위기']].map(([key,label])=>`<button role="tab" type="button" data-pet-category="${key}" aria-selected="${petShopCategory===key}">${label}</button>`).join('')}</div><div class="pet-shop">${Object.entries(p.items).filter(([key,item])=>item.category===petShopCategory).map(([key,item])=>`<button type="button" data-pet-item="${key}" class="${p.equipped.includes(key)?'is-equipped':''}" ${petBusy||(!p.owned.includes(key)&&p.coins<item.price)?'disabled':''}>${['character','color'].includes(item.category)?`<div class="pet-look-preview">${petAvatar(p.stage,item.category==='character'?key:'',item.category==='color'?key:(p.equipped.find(k=>k.startsWith('color-'))||''))}</div>`:`<span aria-hidden="true">${item.icon}</span>`}<strong>${esc(item.name)}</strong>${item.description?`<span class="pet-item-description">${esc(item.description)}</span>`:''}<small>${p.owned.includes(key)?(p.equipped.includes(key)?'사용 중 · 해제':'보유 중 · 적용'):item.price+' 코인 · 구매'}</small></button>`).join('')}</div><p class="pet-store-status" role="status">${esc(petMessage||'')}</p></section><details class="pet-guide"><summary>성장 방법과 돌보기 기록</summary><p>네 가지 돌보기마다 하루 한 번 성장 8과 코인 1을 받아요. 돌보기 코인은 하루 최대 4개입니다. 성장 32 · 96 · 192에서 다음 단계가 열립니다. 성장과 보금 코인은 홈페이지 활동 XP와 별도로 쌓여요. 오래 자리를 비워도 상태는 25 아래로 내려가지 않고, 성장 단계는 유지됩니다.</p><ul>${p.history.map(h=>`<li><span>${esc(h.text)}</span><small>${esc(h.time.slice(5,16).replace('T',' '))}</small></li>`).join('')||'<li>첫 돌보기를 해 보세요.</li>'}</ul></details></div>`;updatePetWait();
}
function updatePetWait(){if(location.hash!=='#pet'||!petState)return;const wait=Math.max(0,Math.ceil((petWaitUntil-Date.now())/1000));document.querySelectorAll('[data-pet-care]').forEach(b=>{b.disabled=petBusy||wait>0;});const status=document.querySelector('#pet-action-status');if(status&&!petBusy)status.textContent=wait?'잠깐 쉬어요 · '+wait+'초 뒤 다시 돌볼 수 있어요.':'';}
async function changePet(path,data){if(petBusy)return;petBusy=true;try{const result=await petRequest(path,data);petState=result.pet;petMessage=result.message;petLoaded=true;petWaitUntil=Date.now()+Number(result.pet.care_wait||0)*1000;renderPetPage();return true;}catch(error){const status=document.querySelector('#pet-action-status')||document.querySelector('.pet-welcome .pet-notice');if(status)status.textContent=error.message;const nameStatus=document.querySelector('#pet-name-dialog[open] .pet-notice');if(nameStatus)nameStatus.textContent=error.message;const speech=document.querySelector('.pet-speech');if(speech)speech.textContent=error.message;return false;}finally{petBusy=false;updatePetWait();document.querySelectorAll('[data-pet-item]').forEach(b=>{b.disabled=!petState?.owned.includes(b.dataset.petItem)&&petState?.coins<petState?.items[b.dataset.petItem].price;});}}
document.addEventListener('submit',async e=>{const f=e.target;if(!['pet-adopt-form','pet-name-form'].includes(f.id))return;e.preventDefault();const b=f.querySelector('[type=submit],button');b.disabled=true;const ok=await changePet(f.id==='pet-adopt-form'?'/adopt':'/rename',{name:new FormData(f).get('name')});if(ok&&f.id==='pet-name-form')f.closest('dialog').close();else b.disabled=false;});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-pet-care],[data-pet-item],.pet-name-edit,#pet-retry,[data-pet-category]');if(!b)return;if(b.dataset.petCategory){petShopCategory=b.dataset.petCategory;renderPetPage();return;}if(b.id==='pet-retry'){loadPet();return;}if(b.dataset.petCare){b.disabled=true;await changePet('/care',{action:b.dataset.petCare});return;}if(b.dataset.petItem){b.disabled=true;await changePet('/decorate',{item:b.dataset.petItem});return;}let modal=document.querySelector('#pet-name-dialog');if(!modal){modal=document.createElement('dialog');modal.id='pet-name-dialog';document.body.append(modal);}modal.innerHTML=`<div class="progress-dialog-head"><h2>이름 변경</h2><button type="button" class="dialog-close-icon" aria-label="닫기">×</button></div><form id="pet-name-form" class="board-form"><label>이름<input class="field" name="name" maxlength="12" value="${esc(petState.name)}" required></label><button type="submit" class="primary">저장</button><p class="pet-notice" role="status"></p></form>`;modal.querySelector('.dialog-close-icon').onclick=()=>modal.close();modal.showModal();});
setInterval(updatePetWait,1000);
setInterval(()=>{if(location.hash==='#pet'&&!document.hidden&&!petBusy&&!document.querySelector('dialog[open]'))loadPet();},60000);
